import 'package:firebase_core/firebase_core.dart';

import '../../firebase_options.dart';

/// The single place where Firebase is started. `bootstrap()` calls it once,
/// before any Firebase-backed provider is used. Tests and tools can pass
/// another implementation.
abstract interface class FirebaseInitializer {
  Future<void> initialize();
}

/// Uses the per-platform options generated by `flutterfire configure`
/// (`lib/firebase_options.dart`).
class DefaultFirebaseInitializer implements FirebaseInitializer {
  const DefaultFirebaseInitializer();

  @override
  Future<void> initialize() async {
    if (Firebase.apps.isNotEmpty) return;
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  }
}
